+            valid = false;
+        } else if (message.getValue().length() > 500) {
+            invalidate(message, "Message must be at most 500 characters");
+            valid = false;
+        }
+        return valid;
+    }
+
+    private void invalidate(com.vaadin.flow.component.HasValidation field, String errorMessage) {
+        field.setErrorMessage(errorMessage);
+        field.setInvalid(true);
+    }
+
+    private void refreshMessages() {
+        sentMessages.setItems(messageStore.newestFirst());
+    }
+
+    private boolean hasUnsavedInput() {
+        return !name.getValue().isEmpty() || !email.getValue().isEmpty()
+                || !phone.getValue().isEmpty() || !message.getValue().isEmpty();
+    }
+
+    @Override
+    public void beforeLeave(BeforeLeaveEvent event) {
+        if (!hasUnsavedInput()) {
+            return;
+        }
+        pendingNavigation = event.postpone();
+        showDiscardDialog();
+    }
+
+    private void showDiscardDialog() {
+        Dialog dialog = new Dialog();
+        dialog.setCloseOnEsc(false);
+        dialog.setCloseOnOutsideClick(false);
+        Button keepEditing = new Button("Keep editing", event -> {
+            dialog.close();
+            pendingNavigation.cancel();
+            pendingNavigation = null;
+        });
+        Button discard = new Button("Discard", event -> {
+            dialog.close();
+            BeforeLeaveEvent.ContinueNavigationAction navigation = pendingNavigation;
+            pendingNavigation = null;
+            navigation.proceed();
+        });
+        dialog.add(new HorizontalLayout(keepEditing, discard));
+        dialog.open();
+    }
+}
