+package com.example;
+
+import java.util.ArrayList;
+import java.util.List;
+import java.util.concurrent.CopyOnWriteArrayList;
+
+import org.springframework.stereotype.Service;
+
+/**
+ * Deliberately in-memory: messages remain available while users navigate
+ * between views, without making this small example depend on a database.
+ */
+@Service
+public class MessageStore {
+    private final List<ContactMessage> messages = new CopyOnWriteArrayList<>();
+
+    public void add(ContactMessage message) {
+        messages.addFirst(message);
+    }
+
+    public List<ContactMessage> newestFirst() {
+        return new ArrayList<>(messages);
+    }
+}
